/**
 * Grace period between a failed payment and any status-transition decision.
 * Named per the plan so the eventual grace-period-expiry cron (not built in
 * this phase — see billing.module.ts) reads this instead of a bare literal.
 */
export const DEFAULT_PAYMENT_GRACE_PERIOD_DAYS = 3;

/**
 * RAZORPAY_KEY_ID / RAZORPAY_KEY_SECRET are deliberately NOT required here.
 * Those are the user's own real Razorpay credentials (pasted in by them, not
 * generated by us) — requiring them at boot would mean this service refuses
 * to start at all until that happens, which is worse than letting it boot and
 * failing clearly only when a create-order call is actually attempted. See
 * RazorpayClientFactory for the lazy, call-time check (including the
 * TEST-mode-only `rzp_test_` prefix guard).
 *
 * RAZORPAY_WEBHOOK_SECRET is different: unlike the API keys, it's an
 * arbitrary shared secret (not a recognizable Razorpay-issued credential), so
 * it's safe to require at boot the same way PLATFORM_ADMIN_*_SECRET already is.
 */
const REQUIRED_VARIABLES = ['RAZORPAY_WEBHOOK_SECRET'] as const;

export function validateBillingEnvironment(
  configuration: Record<string, unknown>,
): Record<string, unknown> {
  for (const variable of REQUIRED_VARIABLES) {
    const value = configuration[variable];
    if (typeof value !== 'string' || value.trim().length === 0) {
      throw new Error(`Environment variable ${variable} is required`);
    }
  }

  const webhookSecret = String(configuration.RAZORPAY_WEBHOOK_SECRET);
  if (webhookSecret.length < 16) {
    throw new Error('RAZORPAY_WEBHOOK_SECRET must be at least 16 characters');
  }

  const gracePeriodRaw = configuration.PAYMENT_GRACE_PERIOD_DAYS;
  if (gracePeriodRaw !== undefined) {
    const gracePeriod = Number(gracePeriodRaw);
    if (!Number.isInteger(gracePeriod) || gracePeriod <= 0) {
      throw new Error(
        'Environment variable PAYMENT_GRACE_PERIOD_DAYS must be a positive integer when set',
      );
    }
  }

  return configuration;
}
